  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Safinamide absolute oral bioavailability was 95.0% (83.9–119.3%) after a 50 mg IR tablet in the fasted state, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Bromfenac absolute oral bioavailability was 67% ± 20% after a 50 mg oral dose under fasting conditions compared with IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Rigosertib absolute oral bioavailability was 34.8% after a 560 mg oral dose in the fasting state, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer human absolute bioavailability records, including fasting-state values of 95%, 67%, and 34.8%, support F ≥ 20%. A conflicting low diclofenac dispersible-tablet record is less condition-matched and outweighed by the more consistent high-bioavailability evidence.",
  "evidence_gaps": [
    "Diclofenac evidence is mixed: an absolute F of 0.35 from dispersible tablets conflicts with fasting soft-gel ~50% and other oral records; the low record is less condition-matched and was not used as the molecule-level direction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

